# Try indexing from the end (reverse positions)
# inp[i] = output[3*(6-i), 3*(6-i)+7, 3*(6-i)+14] for i=0..6

test_input = [[4,9,9,6],[4,4,4,6],[4,4,6,4],[1,2,5,1],[4,2,4,2],[4,4,4,4],[2,4,4,6]]
tests = [list(reversed(r)) + r for r in test_input]

output = [[4]*8 for _ in range(21)]

# inp[0] -> out[18, 25, 32=overflow], but let's cap
for i in range(7):
    p1 = 3*(6-i)       # 0,3,6,9,12,15,18
    p2 = 3*(6-i)+7     # 7,10,13,16,19,22,25
    p3 = 3*(6-i)+14    # 14,17,20,23,26=overflow,29,32
    if p1 < 21: output[p1] = list(tests[i])
    if p2 < 21: output[p2] = list(tests[i])
    if p3 < 21: output[p3] = list(tests[i])

print("Pattern: inp[i] -> out[3*(6-i), 3*(6-i)+7, 3*(6-i)+14]:")
for i, row in enumerate(output):
    if any(v != 4 for v in row):
        print(f"  {i}: {row}")

